Here is the root cause:
The bug was caused by the reintroduction of the `XFAIL` macro in the `close_range_cloexec` test after it had been replaced with the `SKIP` macro in previous commits. This inconsistency led to a failure in the build process, as the testing framework had transitioned away from using `XFAIL` for marking tests that are expected to fail. The use of `XFAIL` was no longer valid, resulting in a conflict with the updated testing harness.

Here is the patch:

 TEST(close_range_unshare)
 {
 	int i, ret, status;
 	pid_t pid;
 	int open_fds[101];
-	struct clone_args args = {
+	struct __clone_args args = {
 		.flags = CLONE_FILES,
 		.exit_signal = SIGCHLD,
 	};

 	for (i = 0; i < ARRAY_SIZE(open_fds); i++) {
 		int fd;

 		fd = open("/dev/null", O_RDONLY | O_CLOEXEC);
 		ASSERT_GE(fd, 0) {
 			if (errno == ENOENT)
 				SKIP(return, "Skipping test since /dev/null does not exist");
 		}

 		open_fds[i] = fd;
 	}

 	pid = sys_clone3(&args, sizeof(args));
 	ASSERT_GE(pid, 0);

 	if (pid == 0) {
 		ret = sys_close_range(open_fds[0], open_fds[50],
 				      CLOSE_RANGE_UNSHARE);
 		if (ret)
 			exit(EXIT_FAILURE);

 		for (i = 0; i <= 50; i++)
 			if (fcntl(open_fds[i], F_GETFL) != -1)
 				exit(EXIT_FAILURE);

 		for (i = 51; i <= 100; i++)
 			if (fcntl(open_fds[i], F_GETFL) == -1)
 				exit(EXIT_FAILURE);

 		/* create a couple of gaps */
 		close(57);
 		close(78);
 		close(81);
 		close(82);
 		close(84);
 		close(90);

 		ret = sys_close_range(open_fds[51], open_fds[92],
 				      CLOSE_RANGE_UNSHARE);
 		if (ret)
 			exit(EXIT_FAILURE);

 		for (i = 51; i <= 92; i++)
 			if (fcntl(open_fds[i], F_GETFL) != -1)
 				exit(EXIT_FAILURE);

 		for (i = 93; i <= 100; i++)
 			if (fcntl(open_fds[i], F_GETFL) == -1)
 				exit(EXIT_FAILURE);

 		/* test that the kernel caps and still closes all fds */
 		ret = sys_close_range(open_fds[93], open_fds[99],
 				      CLOSE_RANGE_UNSHARE);
 		if (ret)
 			exit(EXIT_FAILURE);

 		for (i = 93; i <= 99; i++)
 			if (fcntl(open_fds[i], F_GETFL) != -1)
 				exit(EXIT_FAILURE);

 		if (fcntl(open_fds[100], F_GETFL) == -1)
 			exit(EXIT_FAILURE);

 		ret = sys_close_range(open_fds[100], open_fds[100],
 				      CLOSE_RANGE_UNSHARE);
 		if (ret)
 			exit(EXIT_FAILURE);

 		if (fcntl(open_fds[100], F_GETFL) != -1)
 			exit(EXIT_FAILURE);

 		exit(EXIT_SUCCESS);
 	}

 	EXPECT_EQ(waitpid(pid, &status, 0), pid);
 	EXPECT_EQ(true, WIFEXITED(status));
 	EXPECT_EQ(0, WEXITSTATUS(status));
 }

 TEST(close_range_unshare_capped)
 {
 	int i, ret, status;
 	pid_t pid;
 	int open_fds[101];
-	struct clone_args args = {
+	struct __clone_args args = {
 		.flags = CLONE_FILES,
 		.exit_signal = SIGCHLD,
 	};

 	for (i = 0; i < ARRAY_SIZE(open_fds); i++) {
 		int fd;

 		fd = open("/dev/null", O_RDONLY | O_CLOEXEC);
 		ASSERT_GE(fd, 0) {
 			if (errno == ENOENT)
 				SKIP(return, "Skipping test since /dev/null does not exist");
 		}

 		open_fds[i] = fd;
 	}

 	pid = sys_clone3(&args, sizeof(args));
 	ASSERT_GE(pid, 0);

 	if (pid == 0) {
 		ret = sys_close_range(open_fds[0], UINT_MAX,
 				      CLOSE_RANGE_UNSHARE);
 		if (ret)
 			exit(EXIT_FAILURE);

 		for (i = 0; i <= 100; i++)
 			if (fcntl(open_fds[i], F_GETFL) != -1)
 				exit(EXIT_FAILURE);

 		exit(EXIT_SUCCESS);
 	}

 	EXPECT_EQ(waitpid(pid, &status, 0), pid);
 	EXPECT_EQ(true, WIFEXITED(status));
 	EXPECT_EQ(0, WEXITSTATUS(status));
 }

 TEST(close_range_cloexec)
 {
 	int i, ret;
 	int open_fds[101];
 	struct rlimit rlimit;

 	for (i = 0; i < ARRAY_SIZE(open_fds); i++) {
 		int fd;

 		fd = open("/dev/null", O_RDONLY);
 		ASSERT_GE(fd, 0) {
 			if (errno == ENOENT)
-				XFAIL(return, "Skipping test since /dev/null does not exist");
+				SKIP(return, "Skipping test since /dev/null does not exist");
 		}

 		open_fds[i] = fd;
 	}

 	ret = sys_close_range(1000, 1000, CLOSE_RANGE_CLOEXEC);
 	if (ret < 0) {
 		if (errno == ENOSYS)
-			XFAIL(return, "close_range() syscall not supported");
+			SKIP(return, "close_range() syscall not supported");
 		if (errno == EINVAL)
-			XFAIL(return, "close_range() doesn't support CLOSE_RANGE_CLOEXEC");
+			SKIP(return, "close_range() doesn't support CLOSE_RANGE_CLOEXEC");
 	}

 	/* Ensure the FD_CLOEXEC bit is set also with a resource limit in place.  */
 	ASSERT_EQ(0, getrlimit(RLIMIT_NOFILE, &rlimit));
 	rlimit.rlim_cur = 25;
 	ASSERT_EQ(0, setrlimit(RLIMIT_NOFILE, &rlimit));

 	/* Set close-on-exec for two ranges: [0-50] and [75-100].  */
 	ret = sys_close_range(open_fds[0], open_fds[50], CLOSE_RANGE_CLOEXEC);
 	ASSERT_EQ(0, ret);
 	ret = sys_close_range(open_fds[75], open_fds[100], CLOSE_RANGE_CLOEXEC);
 	ASSERT_EQ(0, ret);

 	for (i = 0; i <= 50; i++) {
 		int flags = fcntl(open_fds[i], F_GETFD);

 		EXPECT_GT(flags, -1);
 		EXPECT_EQ(flags & FD_CLOEXEC, FD_CLOEXEC);
 	}

 	for (i = 51; i <= 74; i++) {
 		int flags = fcntl(open_fds[i], F_GETFD);

 		EXPECT_GT(flags, -1);
 		EXPECT_EQ(flags & FD_CLOEXEC, 0);
 	}

 	for (i = 75; i <= 100; i++) {
 		int flags = fcntl(open_fds[i], F_GETFD);

 		EXPECT_GT(flags, -1);
 		EXPECT_EQ(flags & FD_CLOEXEC, FD_CLOEXEC);
 	}

 	/* Test a common pattern.  */
 	ret = sys_close_range(3, UINT_MAX, CLOSE_RANGE_CLOEXEC);
 	for (i = 0; i <= 100; i++) {
 		int flags = fcntl(open_fds[i], F_GETFD);

 		EXPECT_GT(flags, -1);
 		EXPECT_EQ(flags & FD_CLOEXEC, FD_CLOEXEC);
 	}
 }



